UPDATE orders
SET total_price = (
SELECT COALESCE(SUM(order_price), 0)
FROM order_details
WHERE order_id = #{orderId}
)
WHERE order_id = #{orderId}

mapper.select:
SELECT COUNT(*)
FROM order_details
WHERE order_id = #{orderId}

SELECT total_price
FROM orders
WHERE order_id = #{orderId}

SELECT o.order_id AS orderId, o.order_at AS orderAt, i.ingredient_name AS ingredientName, COUNT(DISTINCT od.ingredient_id) AS ingredientCount, o.total_price AS totalPrice, od.order_status AS orderStatus, od.store_at AS storeAt
FROM orders o
JOIN order_details od ON o.order_id = od.order_id
JOIN ingredients i ON od.ingredient_id = i.ingredient_id
WHERE o.store_id = #{storeId}
AND o.order_at >= #{startDate} AND o.order_at < #{endDate}
AND od.store_at >= #{startDate} AND od.store_at < #{endDate}
GROUP BY o.order_id, o.order_at, o.total_price

